// Run: node test.mjs
import assert from 'node:assert';
import { jpegToPdf, jpegSize } from './pdf.js';

const JPG = ''; // 6x4 red

assert.deepStrictEqual(jpegSize(atob(JPG)), [6, 4]);

for (const [w, h, unit] of [[3, 2, 1], [1200, 50000, 3]]) {
  const pdf = atob(jpegToPdf(JPG, w, h));
  assert.match(pdf, new RegExp(`/UserUnit ${unit}/`));
  assert.match(pdf, /\/Width 6\/Height 4\//);
  // Every xref offset must point at its object header.
  const xref = +pdf.match(/startxref\n(\d+)/)[1];
  const offsets = [...pdf.slice(xref).matchAll(/(\d{10}) 00000 n/g)].map(m => +m[1]);
  assert.strictEqual(offsets.length, 5);
  offsets.forEach((o, i) => assert(pdf.startsWith(`${i + 1} 0 obj`, o), `obj ${i + 1} offset`));
}
console.log('ok');
